import{_ as t,c as e,a0 as s,o as d}from"./chunks/framework.B6JXc2q-.js";const h=JSON.parse('{"title":"小米妙播（MiPlay）本地推流实验记录","description":"","frontmatter":{},"headers":[],"relativePath":"maintenance/2026-11-01-miplay-local-audio-experiment.md","filePath":"maintenance/2026-11-01-miplay-local-audio-experiment.md"}'),n={name:"maintenance/2026-11-01-miplay-local-audio-experiment.md"};function l(o,a,p,i,c,r){return d(),e("div",null,a[0]||(a[0]=[s(`<h1 id="小米妙播-miplay-本地推流实验记录" tabindex="-1">小米妙播（MiPlay）本地推流实验记录 <a class="header-anchor" href="#小米妙播-miplay-本地推流实验记录" aria-label="Permalink to &quot;小米妙播（MiPlay）本地推流实验记录&quot;">​</a></h1><p>日期：2026-11-01 目标：验证「不经小米云、在局域网内把音频 URL/流交给音箱」是否可行，用以绕开 passToken 每 ~84 小时失效的问题。</p><h2 id="结论摘要" tabindex="-1">结论摘要 <a class="header-anchor" href="#结论摘要" aria-label="Permalink to &quot;结论摘要&quot;">​</a></h2><table tabindex="0"><thead><tr><th>结论</th><th>证据强度</th><th>说明</th></tr></thead><tbody><tr><td>妙播发现层可用</td><td>强</td><td>mDNS <code>_lyra-mdns._udp</code> / <code>_mi-connect._udp</code> 查询带 QU 位（qclass <code>0x8001</code>）时，音箱正常应答 PTR/SRV/TXT/A/RR</td></tr><tr><td>控制通道 8899 可用</td><td>强</td><td>TCP 连接后音箱主动下发 DEVICE_ID 帧</td></tr><tr><td>鉴权无证书、无账号</td><td>强</td><td><code>auth_key = md5(map(sip+sp+cip+cp))</code>，纯 IP/端口推导；HMAC 校验通过即建立安全通道</td></tr><tr><td>发送端可完整推流</td><td>强</td><td>旧手机（FusionPlay 接收端）成功播放本实现推送的 60s AAC 正弦波（UI 显示 Test Tone 1:00/1:00）</td></tr><tr><td>OH2P 接受 wrapper OPEN</td><td>强</td><td>回 <code>{&quot;result&quot;:&quot;0&quot;}</code>，但随后不发起 RTSP</td></tr><tr><td>OH2P 拒绝 raw OPEN</td><td>强</td><td>直接断开控制连接</td></tr><tr><td>OH2P 额外校验内容</td><td>未知</td><td><code>SET_PLAY_SOURCE</code>/<code>SET_MEDIA_INFO</code>/<code>GET_DEVICE_INFO</code> 均静默吞掉</td></tr></tbody></table><h2 id="协议结构" tabindex="-1">协议结构 <a class="header-anchor" href="#协议结构" aria-label="Permalink to &quot;协议结构&quot;">​</a></h2><h3 id="_1-发现-mdns" tabindex="-1">1. 发现（mDNS） <a class="header-anchor" href="#_1-发现-mdns" aria-label="Permalink to &quot;1. 发现（mDNS）&quot;">​</a></h3><ul><li>服务类型：<code>_lyra-mdns._udp.local</code>（Lyra）、<code>_mi-connect._udp.local</code></li><li><strong>关键</strong>：查询的 qclass 必须带 QU 位（<code>0x8001</code>），否则音箱不应答</li><li>应答样例（OH2P）： <ul><li><code>PTR _lyra-mdns._udp.local → 207A13E0._lyra-mdns._udp.local</code></li><li><code>SRV → 207A13E0.local:5353</code></li><li><code>TXT AppData=...</code>（含 device_id / mac / 名称）</li><li><code>A → 192.168.7.125</code></li></ul></li><li><code>_mi-connect</code> SRV 指向 <code>:56666</code>（UDP 发现端口），TXT 含 <code>idHash/dev/sec/version/apps</code></li></ul><h3 id="_2-控制通道-tcp-8899" tabindex="-1">2. 控制通道（TCP 8899） <a class="header-anchor" href="#_2-控制通道-tcp-8899" aria-label="Permalink to &quot;2. 控制通道（TCP 8899）&quot;">​</a></h3><p>帧头 9 字节：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&#39;$&#39;(0x24) | outer_type:u8 | command:u8 | value_type:u16(be) | length:u32(be)</span></span></code></pre></div><ul><li><code>outer_type</code>：<code>0x00</code> = raw，<code>0x14</code> = wrapper 命名空间</li><li>加密帧 body 以 <code>00 07 01 e0</code> 开头，后接 <code>pad:u8 | integrity:u32(be) | ciphertext</code></li></ul><p>加密：</p><ul><li>AES-128-CBC，key 与初始 IV 均取 <code>auth_key</code> 前 16 字节（ASCII）</li><li>零填充（非 PKCS#7），pad 值写入帧头</li><li>IV 链式：下一帧 IV = 上一帧密文末 16 字节</li><li>integrity = 自定义 CRC32（多项式 <code>0x04c11db7</code>，表项字节交换，初值 <code>0xffffffff</code>，无最终异或）</li></ul><p><code>auth_key</code> 推导：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>value  = 服务端IP + 服务端端口 + 客户端IP + 客户端端口   （字符串直接拼接）</span></span>
<span class="line"><span>mapped = 每个 ASCII 数字字符 +0x31（&#39;0&#39;→&#39;a&#39; … &#39;9&#39;→&#39;j&#39;）</span></span>
<span class="line"><span>auth_key = hex(md5(mapped))    # 32 hex 字符，取前 16 字节作 AES key</span></span></code></pre></div><blockquote><p>顺序必须是<strong>服务端在前</strong>，反过来密钥不匹配。</p></blockquote><p>wrapper 包装（outer_type=0x14）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>key_len:u8 | key | data_type:u32(le, 固定30) | data_len:u8 | data</span></span></code></pre></div><h3 id="_3-鉴权流程-实测通过网络" tabindex="-1">3. 鉴权流程（实测通过网络） <a class="header-anchor" href="#_3-鉴权流程-实测通过网络" aria-label="Permalink to &quot;3. 鉴权流程（实测通过网络）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>S→C  DEVICE_ID  (0x28)   body = 16 位数字字符串</span></span>
<span class="line"><span>C→S  SAFETY_INFO (0x00)  outer=0x14, 明文 wrap(&quot;cmd&quot;, 加密参数JSON)</span></span>
<span class="line"><span>S→C  SAFETY_INFO_ACK (0x01) outer=0x14, 明文 wrap(&quot;ack&quot;, {...aesIvType:2...})</span></span>
<span class="line"><span>S→C  SAFETY_AUTH (0x02)  outer=0x14, 加密 wrap(&quot;cmd&quot;, {&quot;authMsg&quot;: &lt;challenge&gt;})</span></span>
<span class="line"><span>C→S  SAFETY_AUTH (0x02)  outer=0x14, 加密 wrap(&quot;cmd&quot;, 自己的 challenge)</span></span>
<span class="line"><span>C→S  SAFETY_AUTH_ACK (0x03) outer=0x14, 加密 wrap(&quot;ack&quot;, {&quot;authMsgAck&quot;: hmac})</span></span>
<span class="line"><span>S→C  SAFETY_AUTH_ACK (0x03) outer=0x14, 加密</span></span></code></pre></div><p><code>hmac = hmac_sha256(auth_key_ascii_bytes, peer_challenge_ascii)</code></p><p>安全通道建立后<strong>无任何设备证书校验</strong>，<code>vendor_attestation</code> 概念在该层不存在。</p><h3 id="_4-命令表-关键部分" tabindex="-1">4. 命令表（关键部分） <a class="header-anchor" href="#_4-命令表-关键部分" aria-label="Permalink to &quot;4. 命令表（关键部分）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>命令</th><th>值</th><th>方向</th></tr></thead><tbody><tr><td>DEVICE_ID</td><td>0x28</td><td>S→C</td></tr><tr><td>AUTH_ACK</td><td>0x29</td><td>C→S</td></tr><tr><td>SAFETY_INFO / ACK</td><td>0x00 / 0x01</td><td>C→S / S→C</td></tr><tr><td>SAFETY_AUTH / ACK</td><td>0x02 / 0x03</td><td>双向</td></tr><tr><td>GET_DEVICE_INFO / ACK</td><td>0x1e / 0x1f</td><td>C→S / S→C</td></tr><tr><td>SET_DEVICE_INFO / ACK</td><td>0x58 / 0x59</td><td>C→S / S→C</td></tr><tr><td>OPEN / ACK</td><td>0x00 / 0x01</td><td>C→S / S→C</td></tr><tr><td>SET_MEDIA_INFO / ACK</td><td>0x12 / 0x13</td><td>C→S / S→C</td></tr><tr><td>SET_VOLUME / ACK</td><td>0x0c / 0x0d</td><td>双向</td></tr><tr><td>PAUSE/RESUME</td><td>0x04/0x06</td><td>双向</td></tr><tr><td>NOTIFY</td><td>0x22</td><td>S→C</td></tr><tr><td>SET_PLAY_SOURCE / ACK</td><td>0x40 / 0x41</td><td>C→S / S→C</td></tr><tr><td>SET_MIRROR_KEY / ACK</td><td>0x6c / 0x6d</td><td>C→S / S→C</td></tr></tbody></table><h3 id="_5-媒体会话" tabindex="-1">5. 媒体会话 <a class="header-anchor" href="#_5-媒体会话" aria-label="Permalink to &quot;5. 媒体会话&quot;">​</a></h3><p><code>OPEN</code> 的 body（加密后直接是字符串，<strong>raw，不带 wrapper</strong>）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>wfd://&lt;发送端IP&gt;:&lt;RTSP端口&gt;?mirrorMode=1</span></span></code></pre></div><p>接收端收到后<strong>主动连接该地址</strong>，建立 3 条 TCP（control / image / multi）。</p><p>RTSP 交互（发送端是 server）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>C→S? 发送端先发: OPTIONS * RTSP/1.0 (CSeq 1)</span></span>
<span class="line"><span>接收端回 200 并发 OPTIONS *</span></span>
<span class="line"><span>发送端回 200，然后发 GET_PARAMETER（wfd_audio_codecs_v2）</span></span>
<span class="line"><span>接收端回 200 + 能力:</span></span>
<span class="line"><span>    wfd_audio_codecs_v2: 15 3 3</span></span>
<span class="line"><span>    wfd_client_rtp_ports: RTP/AVP/TCP;interleaved mode=play</span></span>
<span class="line"><span>收到 SET_PARAMETER(wfd_trigger_method: SETUP) 后接收端发 SETUP（带 MultiPort: image_port=..;multi_port=..）</span></span>
<span class="line"><span>发送端回 200 + Session + Transport</span></span>
<span class="line"><span>接收端发 PLAY，发送端回 200，开始推流</span></span></code></pre></div><blockquote><p>实测 FusionPlay 会跳过 SETUP 直接 PLAY；媒体端口可用&quot;最后建立的数据连接&quot;兜底。</p></blockquote><p>媒体格式：</p><ul><li>RTP over TCP，独立数据连接上发<strong>裸 RTP</strong>（无 interleaved 前缀）</li><li>RTP 头 12 字节，PT=33（MP2T），时钟 90000 Hz</li><li>payload = MPEG-TS（每包 7×188 = 1316 字节）</li><li>内含 AAC-LC 48000 Hz 立体声，每帧 1024 样本 → 时间戳步进 1920</li></ul><h2 id="实测记录" tabindex="-1">实测记录 <a class="header-anchor" href="#实测记录" aria-label="Permalink to &quot;实测记录&quot;">​</a></h2><h3 id="对-fusionplay-旧手机-192-168-7-164" tabindex="-1">对 FusionPlay（旧手机，192.168.7.164） <a class="header-anchor" href="#对-fusionplay-旧手机-192-168-7-164" aria-label="Permalink to &quot;对 FusionPlay（旧手机，192.168.7.164）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SET_PLAY_SOURCE → 0x41 ACK</span></span>
<span class="line"><span>SET_MEDIA_INFO  → 0x13 ACK</span></span>
<span class="line"><span>OPEN (raw)      → 0x01 OPEN_ACK [0,0,0,0,0]</span></span>
<span class="line"><span>RTSP            3 条连接建立，OPTIONS/GET_PARAMETER/PLAY 全通</span></span>
<span class="line"><span>推流            RTP/MPEG-TS 1316B × 921 包，60s</span></span>
<span class="line"><span>结果            旧手机播放出「Test Tone」，进度 1:00/1:00</span></span></code></pre></div><h3 id="对-oh2p-192-168-7-125" tabindex="-1">对 OH2P（192.168.7.125） <a class="header-anchor" href="#对-oh2p-192-168-7-125" aria-label="Permalink to &quot;对 OH2P（192.168.7.125）&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>SET_PLAY_SOURCE → 无响应</span></span>
<span class="line"><span>SET_MEDIA_INFO  → 无响应</span></span>
<span class="line"><span>GET_DEVICE_INFO → 无响应</span></span>
<span class="line"><span>OPEN (raw)      → 连接被断开</span></span>
<span class="line"><span>OPEN (wrapper)  → 0x01 ACK {&quot;result&quot;:&quot;0&quot;}，随后无 RTSP 连接，40s 后断开</span></span></code></pre></div><h2 id="未解决的问题" tabindex="-1">未解决的问题 <a class="header-anchor" href="#未解决的问题" aria-label="Permalink to &quot;未解决的问题&quot;">​</a></h2><p>音箱 OH2P 在 OPEN 之后还有一层校验，FusionPlay 没有。可能方向：</p><ol><li>要求 SET_DEVICE_INFO 用 TLV 格式（<code>00 01 55</code> 开头 + key/value 表）而非 JSON</li><li>要求先 SET_MIRROR_KEY 下发媒体密钥</li><li>发送端身份需与米家账号关联（通过云端预登记）</li><li>OPEN 的 URL 参数有其他要求</li></ol><p><strong>下一步</strong>：抓一次小米 12S → OH2P 的真实投送流量（需 ARP 欺骗，将音箱到手机的流量引至 192.168.7.178 抓取），对照本实现逐帧比较。</p><h2 id="复现资产" tabindex="-1">复现资产 <a class="header-anchor" href="#复现资产" aria-label="Permalink to &quot;复现资产&quot;">​</a></h2><ul><li><code>send1.py</code>：发送端完整实现（控制通道 + RTSP server + RTP 推流） <ul><li>用法：<code>python3 send1.py &lt;接收端IP&gt;</code></li><li>依赖：<code>cryptography</code></li><li>测试音频：<code>/tmp/test.ts</code>（60s AAC/TS，由容器内 ffmpeg 生成）</li></ul></li><li>关键探针：<code>probe_lyra_exact.py</code>（QU 位发现）、<code>play10.py</code>（鉴权 + 帧解析）</li></ul>`,44)]))}const _=t(n,[["render",l]]);export{h as __pageData,_ as default};
